import heapq


def stable_matching(proposers, receivers):
    receiver_rank = {
        receiver: {proposer: rank for rank, proposer in enumerate(preferences)}
        for receiver, preferences in receivers.items()
    }

    next_choice = {proposer: 0 for proposer in proposers}
    free_proposers = list(proposers)
    heapq.heapify(free_proposers)

    receiver_matches = {}
    proposer_matches = {}

    while free_proposers:
        proposer = heapq.heappop(free_proposers)
        receiver = proposers[proposer][next_choice[proposer]]
        next_choice[proposer] += 1

        current = receiver_matches.get(receiver)

        if current is None:
            receiver_matches[receiver] = proposer
            proposer_matches[proposer] = receiver
        elif receiver_rank[receiver][proposer] < receiver_rank[receiver][current]:
            receiver_matches[receiver] = proposer
            proposer_matches[proposer] = receiver
            del proposer_matches[current]
            heapq.heappush(free_proposers, current)
        else:
            heapq.heappush(free_proposers, proposer)

    return proposer_matches
